mapper.select:
select g.id, g.subject_name AS subjectName, g.user_id AS userId, u.real_name AS userName,
g.code,
null as code,
(SELECT COUNT(*) FROM t_user_subject ks JOIN t_user k ON ks.user_id = k.id WHERE ks.subject_id = g.id AND ks.is_deleted = 0 AND k.is_deleted = 0 AND k.id != g.user_id) AS subjectCount, g.create_time AS createTime, (SELECT ks.join_time FROM t_user_subject ks WHERE ks.subject_id = g.id AND ks.user_id = #{userId} AND ks.is_deleted = 0) AS joinTime from t_subject g left join t_user u on g.user_id = u.id where g.is_deleted = 0
and g.subject_name LIKE CONCAT('%', #{subjectName}, '%')
and u.real_name = #{userName}
and date(g.create_time) = #{createDate}
and g.id in
#{gId}
and g.id = -1

select id, subject_name, user_id, code, create_time, is_deleted
from t_subject
where user_id = #{userId} and subject_name = #{subjectName}

mapper.update:
UPDATE t_subject
SET is_deleted = 0, user_id = #{userId}, code = #{code}
WHERE id = #{id}
